import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTORS = {"clv": .30, "peer": .25, "reversal": .20, "momentum": .17, "intraday": .08}
MIN_W, MAX_W, CADENCE = .015, .16, 10
last_decision = None


def rank(x):
    out = {s: .5 for s in UNIVERSE}
    valid = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    n = len(valid)
    if n > 1:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.) / n
    return out


def project(raw):
    # Iterative box/simplex projection: complete, long-only allocation.
    w = {s: max(0., float(raw.get(s, 0.))) for s in UNIVERSE}
    for _ in range(50):
        free = [s for s in UNIVERSE if MIN_W < w[s] < MAX_W]
        fixed = [s for s in UNIVERSE if s not in free]
        for s in fixed:
            w[s] = min(MAX_W, max(MIN_W, w[s]))
        rem = 1. - sum(w[s] for s in fixed)
        if not free:
            break
        base = sum(max(w[s], 1e-9) for s in free)
        nw = {s: rem * max(w[s], 1e-9) / base for s in free}
        if all(MIN_W <= nw[s] <= MAX_W for s in free):
            w.update(nw)
            break
        w.update(nw)
    # A final normalization is safe and keeps numerical sum exactly one.
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_decision
    account = get_account_dict()
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=90)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df.close, dtype=float)
        h = np.asarray(df.high, dtype=float)
        l = np.asarray(df.low, dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.
        data[s] = (c, h, l, r, str(df.iloc[-1].date))
    if len(data) < 12:
        return
    date = max(v[4] for v in data.values())
    if last_decision is not None:
        try:
            elapsed = (np.datetime64(date, "D") - np.datetime64(last_decision, "D")) / np.timedelta64(1, "D")
            if elapsed < CADENCE:
                return
        except Exception:
            return

    clv, peer, reversal, momentum, intraday, invvol, five = {}, {}, {}, {}, {}, {}, {}
    for s, (c, h, l, r, _) in data.items():
        if len(r) < 22:
            continue
        clv[s] = float(np.mean((2*c[-3:] - h[-3:] - l[-3:]) / np.maximum(h[-3:] - l[-3:], 1e-12)))
        five[s] = float(c[-1] / max(c[-6], 1e-12) - 1.)
        reversal[s] = -float(np.mean(r[-5:]))
        intraday[s] = -float(r[-1])
        vol = max(float(np.std(r[-20:])), .008)
        invvol[s] = 1. / vol
        momentum[s] = float((c[-1] / max(c[-21], 1e-12) - 1.) / (vol + .01))
    med = float(np.median(list(five.values())))
    peer = {s: v - med for s, v in five.items()}
    ranked = {k: rank(v) for k, v in (("clv", clv), ("peer", peer), ("reversal", reversal), ("momentum", momentum), ("intraday", intraday))}
    score = {s: sum(FACTORS[k] * ranked[k][s] for k in FACTORS) for s in UNIVERSE}

    # Sideways-to-bearish assessment: rotate risk toward tradable defensives.
    if "SPX" in data:
        c = data["SPX"][0]
        if c[-1] < c[-21] and c[-1] < c[-6]:
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] += .18
            for s in ("BTC", "ETH", "WTI"):
                score[s] = max(.05, score[s] - .10)
    avg_iv = float(np.mean(list(invvol.values()))) if invvol else 1.
    raw = {s: max(.01, score[s]) * (.78 + .22 * invvol.get(s, avg_iv) / max(avg_iv, 1e-12)) for s in UNIVERSE}
    weights = project(raw)
    vals = np.array([score[s] for s in UNIVERSE], dtype=float)
    sd = max(float(vals.std()), 1e-12)
    forecast = {s: .01 * (score[s] - float(vals.mean())) / sd for s in UNIVERSE}

    factor_ids = []
    try:
        p = Path(__file__).parent / "factors" / "factor_ensemble.json"
        obj = json.loads(p.read_text(encoding="utf-8"))
        factor_ids = [str(x.get("factor_id")) for x in obj.get("selected_factors", []) if isinstance(x, dict) and x.get("factor_id")]
    except (OSError, ValueError, TypeError):
        pass
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=factor_ids[:10], horizon_days=10)
    last_decision = date

